import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { FaShieldAlt, FaEye, FaEyeSlash, FaEnvelope, FaLock } from "react-icons/fa";
import "./Login.css";

const Login = () => {
  const navigate = useNavigate();

  const [showPassword, setShowPassword] = useState(false);

  const [loginData, setLoginData] = useState({
    email: "",
    password: "",
    remember: false,
  });

  const handleChange = (e) => {
    const { name, value, checked, type } = e.target;

    setLoginData({
      ...loginData,
      [name]: type === "checkbox" ? checked : value,
    });
  };

  const handleSubmit = async (e) => {
  e.preventDefault();

  if (!loginData.email || !loginData.password) {
    alert("Please fill all fields");
    return;
  }

  try {
    const response = await axios.post(
      "http://127.0.0.1:8000/api/login/",
      {
        email: loginData.email,
        password: loginData.password,
      }
    );

    console.log(response.data);

    alert("Login Successful");

    // Store token if using JWT
    if (response.data.access) {
      localStorage.setItem("access", response.data.access);
      localStorage.setItem("refresh", response.data.refresh);
    }

    // Store user data (optional)
    if (response.data.user) {
      localStorage.setItem("user", JSON.stringify(response.data.user));
    }

    navigate("/dashboard");

  } catch (error) {
    console.error(error);

    if (error.response) {
      alert(error.response.data.message || "Invalid Email or Password");
    } else {
      alert("Server Error");
    }
  }
};
  return (
    <div className="login-page">

      <div className="login-left">

        <FaShieldAlt className="shield" />

        <h1>Compliance Management System</h1>

        <p>
          Securely manage audits, findings, corrective actions,
          documents, reports and compliance.
        </p>

      </div>

      <div className="login-right" >

        <div className="login-card">

          <h1 > WELCOME </h1>

          <p>Login to continue</p>

          <form onSubmit={handleSubmit}>

            <div className="input-box">

              <FaEnvelope className="icon"/>

              <input
                type="email"
                name="email"
                placeholder="Email Address"
                value={loginData.email}
                onChange={handleChange}
              />

            </div>

            <div className="input-box">

              <FaLock className="icon"/>

              <input
                type={showPassword ? "text" : "password"}
                name="password"
                placeholder="Password"
                value={loginData.password}
                onChange={handleChange}
              />

              <span
                onClick={() => setShowPassword(!showPassword)}
                className="eye"
              >
                {showPassword ? <FaEyeSlash/> : <FaEye/>}
              </span>

            </div>

            <div className="options">

              <label>

                <input
                  type="checkbox"
                  name="remember"
                  checked={loginData.remember}
                  onChange={handleChange}
                />

                Remember Me

              </label>

              <a href="/">Forgot Password?</a>

            </div>

            <button className="login-btn">
              Login
            </button>

            <div className="register">

              Don't have an account?

              <Link to="/register"> Register</Link>

            </div>

          </form>

        </div>

      </div>

    </div>
  );
};

export default Login;
